UPDATE courses SET sales_page = $json${"version": 1, "hero": {"title": "Here's how therapists use these 3-Steps To Allow them To Launch Their Private Practice & Get Paying Clients", "titleAccent": "...without losing their income or risking their license.", "subtitle": "THERAPIST TO BOSS CLINICIAN", "paragraphs": ["NOW AVAILABLE FOR INSTANT DIGITAL DOWNLOAD", "Download the workbook + watch binge worthy videos to help you get your private practice started on the right track for just $27.", "Delivered instantly. Start your private practice in the next 2 minutes."], "highlights": ["ONLY $27 TODAY", "USUALLY $197", "YOU'RE SAVING $170"], "image": {"src": "/images/source-sales/a7382b5dd859.png", "alt": "Private Practice Starter Suite course and workbook mockup"}}, "sections": [{"id": "self-check", "title": "Check All Of The Questions Where Your Answer Is Yes!", "list": ["Do you **dream of having your own private practice** but feel **overwhelmed by where to start?**", "Are you unsure how to **transition from an employee mindset to thinking like a business owner?**", "Do you worry about **finding your first few clients** without spending hours on social media?", "Are you struggling to **confidently set your rates and pricing structure?**", "Do you feel stuck in indecision and wish you had a **simple, step-by-step roadmap?**", "Are you ready to finally **take action and start your private practice** with clarity and confidence?"]}, {"id": "if-you-checked", "title": "If You Checked ANY Of The Boxes Above,", "paragraphs": ["Then it’s time to take the first step toward **building your dream private practice**—without the stress and uncertainty.", "I want to invite you to snag the **Private Practice Starter Suite**, the **step-by-step system** designed to help therapists like you **gain clarity, attract clients, and confidently step into business ownership!**", "With the right plan in place, you can finally take action **and start seeing results immediately!**"]}, {"id": "case-studies", "title": "Here's a few of our case studies using The Therapist to Boss Clinician Method", "paragraphs": ["I'M READY TO TAKE ACTION - LET'S DO THIS!"]}, {"id": "relate", "title": "CAN YOU RELATE?", "list": ["You feel overwhelmed by the business side of private practice.", "You’re stuck in an **employee mindset** and unsure how to shift into a **business owner mindset.**", "You don’t know how to find clients without spending hours on social media.", "You’re worried about setting your prices too high (or too low!)."]}, {"id": "imagine", "title": "IMAGINE THIS:", "list": ["Having a clear, **step-by-step plan** to start your practice confidently.", "Knowing exactly **how to attract clients** without chasing them online.", "Feeling empowered and in control of your private practice journey!"]}, {"id": "introducing", "title": "Introducing: Private Practice Starter Suite", "paragraphs": ["The **affordable, action-packed mini-course** takes you from feeling stuck to signing your first paying client **without social media overwhelm.**"]}, {"id": "lessons", "title": "Why Private Practice Starter Suite Works So Well: 3 Power-Packed Video Lessons", "intro": "(Short, easily digestible, and actionable!) [$597 value]", "list": ["**VIDEO LESSON 1: From Employee to Business Owner** — Overcome mindset blocks & shift into CEO mode!", "**VIDEO LESSON 2: Choosing Your Niche & Business Model** — Gain clarity on your niche & structure your practice for success.", "**VIDEO LESSON 3: First 3 Clients Blueprint** — Proven referral & visibility strategies to attract clients (without relying solely on social media!)"]}, {"id": "resources", "title": "ACTION ORIENTED RESOURCES!", "list": ["**Mindset Shift Worksheet:** Eliminate fear & step into confidence [$57 value]", "**Niche Clarity & Business Model Worksheet:** Define your ideal clients & pricing [$37 value]", "**Client Attraction Quick-Start Checklist:** Take action immediately with clear steps [$27 value]"]}, {"id": "bonuses", "title": "BONUSES! To Fast-Track Your Success!", "list": ["**Private Practice Starter Checklist:** A complete step-by-step roadmap to launch [$57 value]", "**“From Employee to CEO” Mindset Affirmations:** Shift fear & imposter syndrome into confidence [$57 value]"]}, {"id": "testimonials", "title": "What Students Are Saying", "paragraphs": ["“This course gave me the clarity, tools, and confidence I desperately needed. From setting up my business legally to attracting my first clients—every step was broken down in a way that finally made sense. I’m now seeing clients in my own practice and feel more in control of my future than ever before!” — **Sharon S LPC**, Stillwaters Counseling", "“I had the passion and the license, but the business side of private practice felt overwhelming. The Starter Suite changed everything. Yvette laid it all out—step-by-step, no fluff. I finally understood what I needed to do to build a solid foundation and actually launch. Within weeks, I had my practice name, niche, and systems in place. I’m no longer just dreaming about private practice—I’m living it!” — **Kristan L LCSW**, Intentional Focus Health and Wellness", "“I kept second-guessing myself—worried I’d miss a step or mess something up. The Starter Suite took away all that anxiety. It gave me the structure and support I didn’t even realize I needed. Yvette makes it feel possible, even when it feels scary. Now I have my EIN, my niche is clear, and I’m onboarding my first private clients. This was the push I needed to finally get started!” — **Deanna H LCSW**, DH Counseling"]}, {"id": "meet-yvette", "title": "Meet Yvette Howard", "paragraphs": ["Hey future Boss Clinician, I’m Yvette, a Licensed Clinical Social Worker, Boss Clinician, and business coach who specializes in helping therapists build profitable private practices.", "I started my journey in 2018 with no roadmap and no idea where to begin. After overcoming challenges like navigating legal structures, managing billing, and balancing work while entering motherhood, I also built my own thriving group practice and transitioned it into an employee-based agency in 2021.", "Now, I help therapists like you take the guesswork out of launching your practice, so you can focus on your clients and live the life you desire.", "With over 8 years of experience in mental health and 4 years as a business coach, I’m here to show you that creating a successful private practice is possible with the right foundation and mindset."], "image": {"src": "/images/source-sales/ec60ab91234b.jpg", "alt": "Yvette Howard"}}, {"id": "everything", "title": "HERE'S EVERYTHING YOU GET WHEN YOU ORDER TODAY:", "list": ["3-Step Private Practice Starter Suite Video Course — $597 Value", "Mindset Shift Worksheet — $67 Value", "Niche & Business Model Clarity Worksheet — $97 Value", "Client Attraction Quick-Start Checklist — $47 Value", "BONUS: Private Practice Starter Checklist — $57 Value", "BONUS: “From Employee to CEO” Mindset Affirmations — $27 Value"], "paragraphs": ["**Total Value: $929**", "Get It All For The No-Brainer Price Of: **$27!**", "Secure your spot today and start building your private practice!"]}, {"id": "faq", "title": "Frequently Asked Questions", "paragraphs": ["**Who is this course for?** This mini-course is designed for **licensed therapists** who want to start a private practice but feel overwhelmed. If you need a clear, step-by-step plan—this is for you!", "**I’m already in private practice—will this still help me?** If you feel stuck with marketing, client attraction, or pricing, this course provides clarity on foundational business steps.", "**How long does it take to complete?** Each lesson is under 30 minutes, so you can complete the entire mini-course in just a few hours and start implementing right away!", "**How do I access the course?** After purchase, you’ll receive instant access in your Boss Clinician library. Go through the lessons at your own pace, on your own schedule.", "**What if I need more support after taking the mini-course?** Inside my **Profitable Private Practice Leap Academy Membership**, I provide in-depth training, ongoing coaching, and resources to help you grow your practice beyond the first steps. You’ll get a complete marketing system, pricing strategies, and client attraction frameworks—so you never feel lost in your business.", "**GET STARTED TODAY** — Why Wait? The sooner you start, the sooner you land your first paying clients!", "🔒 **100% Risk-Free** – Lifetime access & step-by-step guidance at an unbeatable price."]}], "footer": "DISCLAIMER: The Private Practice Starter Suite provides actionable guidance to help you start your private practice. However, any case studies, examples, illustrations, or testimonials are for informational purposes only and do not guarantee similar results. Your outcomes may vary significantly based on personal effort, market conditions, and numerous other factors. Any claims or representations regarding income or earnings on this site should not be interpreted as typical or guaranteed results. Past successes or prior financial performance are not indicators of future results. We cannot predict your success, as it depends on factors beyond our control, including your experience, skills, work ethic, and business practices. Therefore, we make no guarantees—express or implied—regarding your ability to generate income. Any financial figures mentioned are for illustrative purposes only. By using this site and its resources, you acknowledge that any business endeavor carries inherent risks and that your success is ultimately determined by your own actions and circumstances."}$json$::jsonb, updated_at = now()
WHERE slug = 'private-practice-starter-suite';
